# check girth via BFS
def girth(adj, n):
    g = float('inf')
    for s in range(n):
        dist = {s:0}; parent={s:-1}
        from collections import deque
        q=deque([s])
        while q:
            u=q.popleft()
            for w in adj[u]:
                if w not in dist:
                    dist[w]=dist[u]+1; parent[w]=u; q.append(w)
                elif parent[u]!=w:
                    g=min(g,dist[u]+dist[w]+1)
    return g
